<?php
declare(strict_types=1);namespace App\Core;use App\Services\SessionService;final class Auth{private static ?array $user=null;private static array $permissions=[];public static function bootstrap():void{try{$uid=(int)($_SESSION['auth_user_id']??0);$sid=(int)($_SESSION['auth_session_id']??0);$ss=new SessionService();if($uid&&$sid&&$ss->isActive($sid,$uid)){$u=self::fetch($uid);if($u&&$u['active']&&in_array($u['account_status'],['ACTIVE','PENDING_ASSIGNMENT'],true)){self::$user=$u;self::loadPermissions();return;}}self::clear();$r=$ss->restoreFromCookie();if($r){self::$user=$r['user'];$_SESSION['auth_user_id']=(int)$r['user']['id'];$_SESSION['auth_session_id']=(int)$r['session_id'];self::loadPermissions();Audit::log('SESSION_RESTORED','persistent_session',(int)$r['session_id']);}}catch(\Throwable $e){Logger::error($e);self::clear();}}public static function check():bool{return self::$user!==null;}public static function user():?array{return self::$user;}public static function id():?int{return self::$user?(int)self::$user['id']:null;}public static function role():?string{return self::$user['role_code']??null;}public static function sessionId():?int{$i=(int)($_SESSION['auth_session_id']??0);return $i?:null;}public static function can(string $p):bool{return self::check()&&((self::role()==='ADMINISTRADOR')||(self::$permissions[$p]??false));}public static function login(array $u,int $sid):void{session_regenerate_id(true);self::$user=$u;$_SESSION['auth_user_id']=(int)$u['id'];$_SESSION['auth_session_id']=$sid;Csrf::rotate();self::loadPermissions();}public static function logoutRuntime():void{self::$user=null;self::$permissions=[];self::clear();session_regenerate_id(true);Csrf::rotate();}public static function requireLogin():void{if(!self::check()){header('Location: '.APP_BASE_URL.'/');exit;}}public static function requirePermission(string $p):void{self::requireLogin();if(!self::can($p)){http_response_code(403);echo '403 - Sin permiso';exit;}}private static function fetch(int $id):?array{$s=Database::pdo()->prepare('SELECT u.*,r.code role_code,r.name role_name FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=? AND u.deleted_at IS NULL LIMIT 1');$s->execute([$id]);return $s->fetch()?:null;}private static function loadPermissions():void{self::$permissions=[];if(!self::$user)return;$s=Database::pdo()->prepare('SELECT p.code,COALESCE(up.allowed,rp.allowed,0) allowed FROM permissions p LEFT JOIN role_permissions rp ON rp.permission_id=p.id AND rp.role_id=? LEFT JOIN user_permissions up ON up.permission_id=p.id AND up.user_id=?');$s->execute([(int)self::$user['role_id'],(int)self::$user['id']]);foreach($s->fetchAll() as $r)self::$permissions[$r['code']]=(bool)$r['allowed'];}private static function clear():void{unset($_SESSION['auth_user_id'],$_SESSION['auth_session_id']);}}
